from common import *
import io
m=load(); s=scp(); out=io.StringIO()
def P(*a): print(*a,file=out)
P("# Paper 05 — first-pass results (public data only)\n")
P("Generated by `p05.py` 2026-11-26. Sources: CDC PLACES 2025 release (model-based estimates; colorectal screening 2022, mammography 2022, cholesterol screening & checkup 2023), CHR supplemental release Mar 2026 (Medicare FFS mammography 2023; PCP 2022; uninsured 2023), State Cancer Profiles (stage and rates, 2019-2023 / 2020-2024). **PLACES estimates are small-area model-based (MRP) estimates that use demographic/geographic predictors; correlations between PLACES measures and county demographics are partly built-in. Treat PLACES-vs-covariate associations as descriptive, and use CHR (claims-based) mammography and SCP outcomes as the less circular tests.**\n")
for c in ['colon_screen','mammouse','cholscreen','checkup']: pass
P("## A. Distribution of screening measures across 82 counties\n")
rows=[]
for v,l in [('pl_colon_screen','Colorectal screening, age 45-75 (PLACES 2022)'),('pl_mammouse','Mammography, women 50-74 (PLACES 2022)'),('mammography_pct','Mammography, Medicare FFS women 65-74 (CHR)'),('pl_cholscreen','Cholesterol screening (PLACES 2023)'),('pl_checkup','Routine checkup past year (PLACES 2023)'),('flu_vacc','Flu vaccination, Medicare FFS (CHR)')]:
    x=m[v].dropna(); rows.append([l,len(x),x.median(),x.min(),x.max()])
P(pd.DataFrame(rows,columns=['Measure','n','Median %','Min %','Max %']).to_markdown(index=False,floatfmt='.1f')); P()
P("## B. Delta region (DRA) and metro status\n")
rows=[]
for v,l in [('pl_colon_screen','Colorectal screening'),('pl_mammouse','Mammography (PLACES)'),('mammography_pct','Mammography (CHR Medicare)'),('pl_cholscreen','Cholesterol screening'),('pl_checkup','Checkup'),('flu_vacc','Flu vaccination (CHR)')]:
    for g,lg in [('dra_county','DRA vs non-DRA'),('nonmetro','Nonmetro vs metro')]:
        a=m[m[g]==1][v].dropna(); b=m[m[g]==0][v].dropna(); u=stats.mannwhitneyu(a,b)
        rows.append([l,lg,len(a),a.median(),len(b),b.median(),a.median()-b.median(),u.pvalue])
P(pd.DataFrame(rows,columns=['Measure','Comparison','n (group=1)','median (1)','n (group=0)','median (0)','Difference (pts)','Mann-Whitney p']).to_markdown(index=False,floatfmt='.3g')); P()
P("## C. Correlates of screening (Spearman; n counties)\n")
rows=[]
for y,ly in [('pl_colon_screen','CRC screening (PLACES)'),('mammography_pct','Mammography (CHR Medicare)'),('pl_mammouse','Mammography (PLACES)'),('pl_cholscreen','Cholesterol screening (PLACES)')]:
    for x,lx in [('pcp_per100k','PCP per 100k'),('uninsured_pct','Uninsured %'),('child_poverty','Child poverty %'),('pct_black_nh','% Black NH'),('median_hh_income','Median HH income')]:
        n,r,p=spearman(m[x],m[y]); rows.append([ly,lx,n,r,p])
P(pd.DataFrame(rows,columns=['Outcome','Predictor','n','rho','p']).to_markdown(index=False,floatfmt='.3f')); P()
m['pcp10']=m.pcp_per100k/10; m['pov10']=m.child_poverty/10
P("## D. OLS (HC3): mammography (CHR, Medicare FFS 65-74) ~ county context\n")
mod,t,n=ols(m,'mammography_pct',['pcp10','pov10','uninsured_pct','nonmetro','dra_county']); P(f"n={n}, R2={mod.rsquared:.2f}\n"); P(t.round(3).to_markdown()); P()
P("## E. Black–White mammography gap (CHR Medicare FFS 65-74; counties with both published)\n")
d=m[['mammo_black','mammo_white']].dropna(); diff=d.mammo_black-d.mammo_white
P(f"- n={len(d)} counties; median White {d.mammo_white.median():.1f}%, median Black {d.mammo_black.median():.1f}%; median diff (B-W) {diff.median():.1f} pts; Black lower in {(diff<0).sum()} counties; Wilcoxon p={stats.wilcoxon(d.mammo_black,d.mammo_white).pvalue:.3g}.")
d=m[['flu_black','flu_white']].dropna(); diff=d.flu_black-d.flu_white
P(f"- Flu vaccination (Medicare FFS): n={len(d)}; median White {d.flu_white.median():.1f}%, Black {d.flu_black.median():.1f}%; median diff {diff.median():.1f} pts; Black lower in {(diff<0).sum()} counties; Wilcoxon p={stats.wilcoxon(d.flu_black,d.flu_white).pvalue:.3g}.\n")
P("## F. Ecological screening → stage/mortality (SCP outcomes vs PLACES/CHR screening)\n")
def cs(ds,col,name):
    x=county_scp(ds)[['fips',col]].rename(columns={col:name}); return x
d=m.copy()
for ds,col,nm in [('crc_late_all','pct_late','crc_pct_late'),('crc_inc_all','rate_per_100k','crc_inc'),('crc_mort_all','rate_per_100k','crc_mort'),('breast_late_all','pct_late','breast_pct_late'),('breast_inc_all','rate_per_100k','breast_inc'),('breast_mort_all','rate_per_100k','breast_mort'),('cervix_inc_all','rate_per_100k','cervix_inc')]:
    d=d.merge(cs(ds,col,nm),on='fips',how='left')
d['crc_mi']=d.crc_mort/d.crc_inc; d['breast_mi']=d.breast_mort/d.breast_inc
rows=[]
for x,lx,y,ly in [('pl_colon_screen','CRC screening %','crc_pct_late','CRC % late stage'),('pl_colon_screen','CRC screening %','crc_inc','CRC incidence'),('pl_colon_screen','CRC screening %','crc_mort','CRC mortality'),('pl_colon_screen','CRC screening %','crc_mi','CRC mort/inc ratio'),
                  ('mammography_pct','Mammography % (CHR)','breast_pct_late','Breast % late stage'),('mammography_pct','Mammography % (CHR)','breast_inc','Breast incidence'),('mammography_pct','Mammography % (CHR)','breast_mort','Breast mortality'),('mammography_pct','Mammography % (CHR)','breast_mi','Breast mort/inc ratio'),
                  ('pl_mammouse','Mammography % (PLACES)','breast_pct_late','Breast % late stage')]:
    n,r,p=spearman(d[x],d[y]); rows.append([lx,ly,n,r,p])
P(pd.DataFrame(rows,columns=['Screening measure','Outcome (SCP)','n counties','rho','p']).to_markdown(index=False,floatfmt='.3f')); P()
P(f"- County availability (published): CRC % late {d.crc_pct_late.notna().sum()}, CRC incidence {d.crc_inc.notna().sum()}, CRC mortality {d.crc_mort.notna().sum()}, breast % late {d.breast_pct_late.notna().sum()}, breast mortality {d.breast_mort.notna().sum()}, cervix incidence {d.cervix_inc.notna().sum()} (cervix too sparse for county analysis).\n")
P("## G. Mississippi vs US and by race (SCP state rows)\n")
rows=[]
for lab,ds in [('CRC incidence, all','crc_inc_all'),('CRC incidence, Black NH','crc_inc_blackNH'),('CRC incidence, White NH','crc_inc_whiteNH'),('CRC mortality, all','crc_mort_all'),('CRC mortality, Black NH','crc_mort_blackNH'),('CRC mortality, White NH','crc_mort_whiteNH'),('CRC % late, all','crc_late_all'),('Breast incidence, all','breast_inc_all'),('Breast incidence, Black NH','breast_inc_blackNH'),('Breast incidence, White NH','breast_inc_whiteNH'),('Breast mortality, all','breast_mort_all'),('Breast mortality, Black NH','breast_mort_blackNH'),('Breast mortality, White NH','breast_mort_whiteNH'),('Breast % late, all','breast_late_all'),('Cervix incidence, all','cervix_inc_all'),('Cervix mortality, all','cervix_mort_all'),('Cervix % late, all','cervix_late_all')]:
    r=state_row(ds); u=state_row(ds,fips='00000'); pl='late' in lab
    rows.append([lab,f"{r.pct_late}%" if pl else f"{r.rate_per_100k} ({r.ci_lo}-{r.ci_hi})",f"{u.pct_late}%" if pl else f"{u.rate_per_100k} ({u.ci_lo}-{u.ci_hi})"])
P(pd.DataFrame(rows,columns=['Measure','Mississippi','United States']).to_markdown(index=False)); P()
b=state_row('breast_mort_blackNH'); w=state_row('breast_mort_whiteNH'); e=rr(b.rate_per_100k,b.ci_lo,b.ci_hi,w.rate_per_100k,w.ci_lo,w.ci_hi)
P(f"- Breast mortality RR Black NH/White NH: {e[0]:.2f} ({e[1]:.2f}-{e[2]:.2f}) with incidence RR {state_row('breast_inc_blackNH').rate_per_100k/state_row('breast_inc_whiteNH').rate_per_100k:.2f} (point ratio of published rates).")
b=state_row('crc_mort_blackNH'); w=state_row('crc_mort_whiteNH'); e=rr(b.rate_per_100k,b.ci_lo,b.ci_hi,w.rate_per_100k,w.ci_lo,w.ci_hi)
P(f"- CRC mortality RR Black NH/White NH: {e[0]:.2f} ({e[1]:.2f}-{e[2]:.2f}).")
P("\nNote: PLACES dental-visit measure excluded: published values (4.9-12.9%) are implausible for adults and need verification [PENDING].")
cols=['fips','county','population','nonmetro','dra_county','pcp_per100k','uninsured_pct','child_poverty','pct_black_nh','pl_colon_screen','pl_mammouse','pl_cholscreen','pl_checkup','mammography_pct','mammo_black','mammo_white','flu_vacc','flu_black','flu_white']
d2=d[cols+['crc_pct_late','crc_inc','crc_mort','breast_pct_late','breast_inc','breast_mort']]
d2.to_csv('results/p05/p05_county_dataset.csv',index=False)
open('results/p05/p05_results.md','w').write(out.getvalue()); print(out.getvalue())
